hooks.command:
[ -n "$MDGRAPH_VAULT" ] && python3 -c '
import json, os, time
newest = 0.0
for root, dirs, files in os.walk(os.environ["MDGRAPH_VAULT"]):
    dirs[:] = [d for d in dirs if not d.startswith(".")]
    for f in files:
        if f.endswith(".md"):
            try:
                newest = max(newest, os.path.getmtime(os.path.join(root, f)))
            except OSError:
                pass
if newest and time.time() - newest > 7200:
    print(json.dumps({"systemMessage": "mdgraph: заметки в vault не обновлялись более 2 часов — можно сохранить итоги сессии (скилл vault-save)."}, ensure_ascii=False))
'; true
